style.css:
/* =========================================================
   Claude.ai — 4K Wide Mode
   Based on actual Claude DOM:
   div.mx-auto.flex.w-full.flex-1.flex-col.max-w-3xl.md:px-2
   ========================================================= */


/* ---------------------------------------------------------
   1. 
   --------------------------------------------------------- */

@media (min-width: 1200px) {

    /*
     * 這就是你 F12 截圖中被選中的元素。
     *
     * Claude 原本：
     * max-w-3xl = 48rem = 768px
     */

    div.mx-auto.flex.w-full.flex-1.flex-col[class~="max-w-3xl"] {

        width: 94% !important;
        max-width: none !important;

        margin-left: auto !important;
        margin-right: auto !important;

        flex-basis: auto !important;

        box-sizing: border-box !important;
    }


    /* -----------------------------------------------------
       2. 
       ----------------------------------------------------- */

  

    div[class~="max-w-3xl"][class~="mx-auto"][class~="flex-1"] {

        width: 94% !important;
        max-width: none !important;

        margin-left: auto !important;
        margin-right: auto !important;

        box-sizing: border-box !important;
    }


    /* -----------------------------------------------------
       3. 
       ----------------------------------------------------- */

    div[class~="max-w-3xl"] .prose,
    div[class~="max-w-3xl"] [class*="prose"] {

        width: 100% !important;
        max-width: none !important;
    }


    /* -----------------------------------------------------
       4. 
       ----------------------------------------------------- */

    div[class~="max-w-3xl"] table {

        width: 100% !important;
        max-width: 100% !important;

        table-layout: auto !important;
    }


    /* -----------------------------------------------------
       5. Code Block
       ----------------------------------------------------- */

    div[class~="max-w-3xl"] pre {

        width: 100% !important;
        max-width: 100% !important;

        overflow-x: auto !important;

        box-sizing: border-box !important;
    }


    div[class~="max-w-3xl"] pre code {

        max-width: none !important;
    }


    /* -----------------------------------------------------
       6. 
       ----------------------------------------------------- */

    div[class~="max-w-3xl"] img {

        max-width: 100% !important;
        height: auto !important;
    }


    /* -----------------------------------------------------
       7. Prompt 
       ----------------------------------------------------- */

  

    form {

        max-width: none !important;
    }


    /* -----------------------------------------------------
       8. 4K 
       ----------------------------------------------------- */

    @media (min-width: 3000px) {

        div.mx-auto.flex.w-full.flex-1.flex-col[class~="max-w-3xl"],
        div[class~="max-w-3xl"][class~="mx-auto"][class~="flex-1"] {

            width: 94% !important;
            max-width: none !important;
        }
    }
}
